const MAX_ROOT_CHUNKS = 16
const ROOT_ACTIONS_PER_CHUNK = 1024
const MAX_WORKTREE_REMOVAL_ENTRIES = 16384
const MAX_WORKTREE_REMOVAL_TOTAL_FILE_BYTES = 4294967296n
